import type { Config } from 'drizzle-kit'

/**
 * Migrations are FILES in `drizzle/`, generated by `npm run db:generate` and
 * committed. Never `db:push`: a schema that only exists in someone's local file
 * has no diff to review, and the first thing a financial database needs is a
 * written history of how its shape changed.
 */
export default {
  dialect: 'sqlite',
  schema: './src/data/sqlite/schema.ts',
  out: './drizzle',
  dbCredentials: {
    // Same default as `src/data/sqlite/client.ts`; `.data/` is git-ignored (ADR-0009).
    url: process.env.DATABASE_PATH ?? './.data/bigorna.db',
  },
  strict: true,
  verbose: true,
} satisfies Config
